--
-- Table structure for table `partecipazione_squadra`
--

DROP TABLE IF EXISTS `partecipazione_squadra`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `partecipazione_squadra` (
  `id_partecipazione` int(11) NOT NULL AUTO_INCREMENT,
  `id_squadra` int(11) NOT NULL,
  `id_stagione` int(11) NOT NULL,
  `id_campionato` int(11) NOT NULL,
  `nome` varchar(100) NOT NULL,
  `girone` char(1) DEFAULT NULL,
  `posizione` int(11) DEFAULT NULL,
  `vittorie` int(11) DEFAULT NULL,
  `sconfitte` int(11) DEFAULT NULL,
  `punti_fatti` int(11) DEFAULT NULL,
  `punti_subiti` int(11) DEFAULT NULL,
  PRIMARY KEY (`id_partecipazione`),
  UNIQUE KEY `id_squadra` (`id_squadra`,`id_stagione`),
  KEY `id_stagione` (`id_stagione`),
  KEY `id_campionato` (`id_campionato`),
  CONSTRAINT `1` FOREIGN KEY (`id_squadra`) REFERENCES `squadra` (`id_squadra`),
  CONSTRAINT `2` FOREIGN KEY (`id_stagione`) REFERENCES `stagione` (`id_stagione`),
  CONSTRAINT `3` FOREIGN KEY (`id_campionato`) REFERENCES `campionato` (`id_campionato`)
) ENGINE=InnoDB AUTO_INCREMENT=117 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

